'use strict';
const KEY='okike_admin_prototype_v1',PREF='okike_admin_preferences_v1';
const roles=['Admin','PM','Head of PM','Finance','Head of Finance','MD','Design','Media'];
const services=['Carpentry','Upholstery','New Build','Renovation','Interior Design','Landscape & Exterior Facade','Other Services'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₦'+Number(n||0).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2});
const today=()=>new Date().toISOString().slice(0,10),uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
function project(id,name,clientId){return{id,name,clientId,service:'Interior Design',route:'Design first',brief:'',docs:[],milestones:[],mobilised:false,events:[]}}
function doc(type,version,body,total=0){return{id:uid('DOC'),type,version,body,total,status:'Draft',sent:null,response:null,evidence:[],created:today()}}
function seed(){let a=project('OK-2026-001','Cedar House Renovation','CL-0001');a.service='Renovation';a.brief='Refresh the living room, replace fitted cabinetry and complete painting. Preserve existing flooring. Client prefers a warm, contemporary finish.';let q=doc('Technical quotation',1,'Living room renovation\nCabinetry, preparation, painting and installation.\nScope and allowances shown here are demonstration data.',2400000);q.status='Submitted';a.docs.push(q);a.milestones=[{id:'MS-1',name:'Cabinetry installation complete',media:true,billing:40,status:'Planned',evidence:[],note:''}];a.events=[{text:'PM submitted Technical quotation v1 for Admin review.',at:new Date().toISOString(),by:'PM'}];let b=project('OK-2026-002','Palmcrest Office','CL-0002');b.brief='Office reception and meeting-room refurbishment.';let qb=doc('Technical quotation',1,'Reception and meeting-room refurbishment. Approved demonstration quotation.',5000000);qb.status='Accepted';qb.sent={date:today(),channel:'Email',recipient:'client@example.test'};qb.response={date:today(),note:'Demonstration client acceptance'};let inv=doc('Invoice',1,'Initial deposit — 60% of approved quotation.',3000000);inv.status='Issued';inv.quoteId=qb.id;inv.percent=60;inv.paid=false;inv.initial=true;let sow=doc('SOW',1,'Reception and meeting-room refurbishment.\nStage 1: Preparation\nStage 2: Installation\nStage 3: Finishing and handover');sow.quoteId=qb.id;sow.status='Awaiting Head of PM';b.docs.push(qb,inv,sow);b.events=[{text:'Finance issued the initial deposit invoice.',at:new Date().toISOString(),by:'Finance'}];return{version:1,clients:[{id:'CL-0001',name:'Ada Okoro',email:'ada@example.test',phone:'',company:''},{id:'CL-0002',name:'Palmcrest Ltd.',email:'client@example.test',phone:'',company:'Palmcrest Ltd.'}],enquiries:[{id:'ENQ-001',name:'Tunde Bello',email:'tunde@example.test',phone:'',channel:'Referral',service:'Interior Design',location:'Lagos',description:'Planning a new apartment interior and needs an early cost estimate.',route:'Planning estimate',budget:'Not yet shared',timeline:'Next quarter',status:'New',notes:'',followup:today(),created:today(),owner:'Admin'}],projects:[a,b],tasks:[]}}
let state,prefs={theme:'light',sound:true,vibration:true,collapsed:false},role='Admin',page='My Workspace',pid=null,tab='Overview',search='',taskFilter='Admin',documentId=null;
try{state=JSON.parse(localStorage.getItem(KEY))||seed();if(state.version!==1)state=seed();Object.assign(prefs,JSON.parse(localStorage.getItem(PREF))||{})}catch{state=seed()}
function feedback(error=false){if(prefs.vibration)navigator.vibrate?.(error?[40,30,40]:25);if(prefs.sound){try{let a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.frequency.value=error?240:640;g.gain.setValueAtTime(.02,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.12);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.12);o.onended=()=>a.close()}catch{}}}
let toastTimer;function toast(s,error=false){let el=document.getElementById('toast');el.textContent=s;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4500);feedback(error)}
function mutate(fn){let before=JSON.stringify(state);try{fn();localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){state=JSON.parse(before);toast(e.message||'Could not save. Please export your records.',true);return false}}
function log(p,text){p.events.unshift({text,at:new Date().toISOString(),by:role})}
function client(p){return state.clients.find(c=>c.id===p.clientId)||{name:'Unknown client'}}
function currentProject(){return state.projects.find(p=>p.id===pid)}
function quote(p){return p.docs.filter(d=>d.type.includes('quotation')).at(-1)}
function sowOf(p){return p.docs.filter(d=>d.type==='SOW').at(-1)}
function acceptedQuote(p){let q=quote(p);return q?.status==='Accepted'?q:null}
function ready(p){if(p.cancelled||cancellationPending(p))return false;let q=acceptedQuote(p),s=sowOf(p);return !!(q&&s?.status==='Client approved'&&s.quoteId===q.id&&p.docs.some(d=>d.type==='Invoice'&&d.initial&&d.quoteId===q.id&&d.paid))}
function allow(r){if(!r.includes(role))throw Error('Switch the demo role to '+r.join(' or ')+' to perform this action.')}
function transition(p,d,action,data={}){assertActive(p);if(!p.docs.some(x=>x.id===d?.id))throw Error('This document belongs to an earlier job cycle.');if(d.type.includes('quotation')&&d!==quote(p))throw Error('Historical quotation versions are read-only.');if(action==='submitQuote'){allow(['PM']);if(!['Draft','Changes requested'].includes(d.status))throw Error('Quotation is not a draft.');d.status='Submitted'}
else if(action==='reviewQuote'){allow(['Admin']);if(d.status!=='Submitted')throw Error('Quotation is not awaiting review.');d.status='Ready to send'}
else if(action==='returnQuote'){allow(['Admin']);if(d.status!=='Submitted')throw Error('Quotation is not awaiting review.');d.status='Changes requested';d.returnNote=data.note}
else if(action==='headSow'){allow(['Head of PM']);if(d.status!=='Awaiting Head of PM')throw Error('SOW is not awaiting this approval.');d.status='Awaiting MD';d.headApproval={date:today(),by:role}}
else if(action==='mdSow'){allow(['MD']);if(d.status!=='Awaiting MD')throw Error('Head of PM approval is required first.');d.status='Ready to send';d.mdApproval={date:today(),by:role}}
else if(action==='returnSow'){allow(['Head of PM','MD']);if((role==='Head of PM'&&d.status!=='Awaiting Head of PM')||(role==='MD'&&d.status!=='Awaiting MD'))throw Error('SOW is not awaiting your approval.');d.status='Changes requested';d.returnNote=data.note}
else if(action==='send'){allow(['Admin']);if(!['Ready to send','Issued','Sent'].includes(d.status))throw Error('Document must complete its review or approval before sending.');d.sent={...data,date:data.date||today()};d.dispatches=[...(d.dispatches||[]),d.sent];d.status='Sent';if(d.replacesQuoteId){let old=p.docs.find(x=>x.id===d.replacesQuoteId);if(old){old.status='Superseded';old.supersededBy=d.id}}}
else if(action==='accept'){allow(['Admin']);if(d.status!=='Sent'||d.type==='Invoice')throw Error('Only a sent quotation or SOW can be accepted.');d.status=d.type==='SOW'?'Client approved':'Accepted';d.response={...data,date:today()}}
else if(action==='clientChanges'){if(d.type.includes('quotation'))throw Error('Choose design/scope revision or price review for quotations.');allow(['Admin']);if(d.status!=='Sent'||d.type==='Invoice')throw Error('Document must be sent first.');d.status='Changes requested';d.response={...data,date:today()}}
else if(action==='paid'){allow(['Finance','Head of Finance']);if(d.type!=='Invoice'||d.paid)throw Error('Select an unpaid invoice.');if(Number(data.amount)!==Number(d.total))throw Error('This prototype requires confirmation of the full invoiced amount.');d.paid=true;d.payment={...data,confirmedBy:role,date:today()}}
else throw Error('Unknown document action.');log(p,d.type+' v'+d.version+': '+({submitQuote:'submitted for Admin review',reviewQuote:'reviewed — ready to send',returnQuote:'returned to PM',headSow:'approved by Head of PM',mdSow:'approved by MD',returnSow:'returned for changes',send:'sent to client',accept:'client approval recorded',clientChanges:'client requested changes',paid:'payment confirmed by Finance'}[action]))}
function approveMilestone(p,m){assertActive(p);allow(['Head of PM']);if(m.status!=='Submitted for Review'||!m.evidence.length)throw Error('A submission with media evidence is required.');m.status='Completed';m.approved={date:today(),by:role};for(let [dept,title] of [[m.media?'Media':null,'Arrange media visit'],[m.billing>0?'Finance':null,'Prepare milestone invoice — '+m.billing+'%']]){if(dept&&!state.tasks.some(t=>t.key===m.id+dept))state.tasks.push({id:uid('TASK'),key:m.id+dept,projectId:p.id,milestoneId:m.id,dept,title:title+' · '+m.name,status:'Open'})}log(p,'Head of PM verified milestone: '+m.name)}
function queue(){let list=[];for(let e of state.enquiries.filter(e=>['New','Follow-up needed'].includes(e.status)))list.push({id:e.id,title:'Assess client enquiry',sub:e.name,source:e.channel,status:e.status,dept:'Admin',page:'Enquiries & Assessment',enquiry:e.id});for(let p of state.projects){if(p.cancelled)continue;if(!quote(p))list.push({title:p.brief?'Prepare quotation':'Record client brief',sub:p.name,source:p.brief?'Design brief ready':'Client intake',status:'Pending',dept:p.brief?'PM':'Design',pid:p.id,tab:'Brief & Quotation'});let dr=latestDesignRequest(p);if(dr&&dr.status!=='Quoted'){let owner=['Awaiting Design','Client requested design changes'].includes(dr.status)?'Design':dr.status==='Client confirmed'?'PM':'Admin';let title=owner==='Design'?'Prepare design/scope revision':owner==='PM'?'Prepare replacement quotation':dr.status==='Ready for client review'?'Send revised design for confirmation':'Follow up on revised design confirmation';list.push({title,sub:p.name,source:'Design revision '+dr.designVersion,status:dr.status,dept:owner,pid:p.id,tab:'Brief & Quotation'})}for(let r of (p.cancellationRequests||[]).filter(r=>r.status==='Awaiting MD'))list.push({title:'Review job cancellation request',sub:p.name,source:'Head of PM',status:r.status,dept:'MD',pid:p.id,tab:'Overview'});for(let d of p.docs){if(d!==quote(p)&&d.type.includes('quotation'))continue;if(d.type==='SOW'&&d!==sowOf(p))continue;let title='',dept='Admin';if(d.status==='Submitted')title='Review quotation';else if(d.status==='Ready to send'||d.status==='Issued')title='Send '+d.type.toLowerCase();else if(d.status==='Sent'&&d.type!=='Invoice')title='Follow up on client approval';else if(d.status==='Changes requested'||d.status==='Price review requested'){title=d.status==='Price review requested'?'Review quotation price':'Revise '+d.type.toLowerCase();dept='PM'}else if(d.status==='Awaiting Head of PM'){title='Review SOW';dept='Head of PM'}else if(d.status==='Awaiting MD'){title='Approve SOW';dept='MD'}else if(d.status==='Draft'){title='Complete quotation';dept='PM'}if(title)list.push({id:d.id,title,sub:p.name,source:dept==='Admin'?(d.type==='Invoice'?'Finance':'PM'): 'Workflow',status:d.status,dept,pid:p.id,doc:d.id});if(d.type==='Invoice'&&!d.paid)list.push({id:d.id+'pay',title:'Confirm invoice payment',sub:p.name,source:'Invoice',status:'Awaiting payment',dept:'Finance',pid:p.id,doc:d.id})}if(acceptedQuote(p)&&!sowOf(p))list.push({title:'Prepare SOW',sub:p.name,source:'Accepted quotation',status:'Pending',dept:'PM',pid:p.id,tab:'SOW & Mobilisation'});if(acceptedQuote(p)&&!p.docs.some(d=>d.type==='Invoice'))list.push({title:'Create deposit invoice',sub:p.name,source:'Accepted quotation',status:'Pending',dept:'Finance',pid:p.id,tab:'Invoices & Payments'});for(let m of p.milestones.filter(m=>m.status==='Submitted for Review'))list.push({title:'Verify milestone completion',sub:p.name,source:'PM',status:'Submitted for Review',dept:'Head of PM',pid:p.id,tab:'Progress & Requests'});if(ready(p)&&!p.mobilised)list.push({title:'Authorise mobilisation',sub:p.name,source:'Deposit + SOW confirmed',status:'Ready',dept:'Head of PM',pid:p.id,tab:'SOW & Mobilisation'})}for(let t of state.tasks.filter(t=>t.status==='Open'&&t.key!==t.projectId+'brief'&&!state.projects.find(p=>p.id===t.projectId)?.cancelled))list.push({title:t.title,sub:state.projects.find(p=>p.id===t.projectId)?.name,source:t.milestoneId?'Verified work milestone':'Client intake',status:'Open',dept:t.dept,pid:t.projectId,tab:t.milestoneId?'Progress & Requests':'Brief & Quotation'});return list}
const badge=s=>`<span class="badge ${['Accepted','Completed','Client approved','Confirmed','Mobilised','Ready'].includes(s)?'green':['Declined','Changes requested'].includes(s)?'red':['Draft','Planned','Withdrawn'].includes(s)?'gray':''}">${esc(s)}</span>`;
const btn=(text,action,extra='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${text}</button>`;
function heading(title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">Administration / ${pid?'Project workspace':'Operations'}</div><h1>${esc(title)}</h1><p class="muted">${esc(desc)}</p></div>${action}</div>`}
function projectButton(p,text='Open project'){return `<button class="link" data-project="${p.id}">${esc(text)} ↗</button>`}
function actionsTable(items){return items.length?`<div class="tablewrap"><table><thead><tr><th>Action / project</th><th>Assigned to</th><th>Status</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><strong>${esc(i.title)}</strong><small>${esc(i.sub||'')} · ${esc(i.source||'')}</small></td><td>${esc(i.dept)}</td><td>${badge(i.status)}</td><td><button class="btn small" ${i.enquiry?`data-enquiry="${i.enquiry}"`:i.doc?`data-doc="${i.doc}" data-pid="${i.pid}"`:`data-project="${i.pid}" data-tab="${i.tab||'Overview'}"`}>Open →</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">All caught up. No pending actions in this view.</div>`}
function dashboard(){let q=queue().filter(i=>role==='Head of Finance'?i.dept==='Finance':i.dept===role);return heading('Your workspace','A clear view of what needs your attention.',btn('＋ New enquiry','newEnquiry','',true))+`<div class="metrics">${[[state.enquiries.filter(e=>['New','Follow-up needed'].includes(e.status)).length,'Enquiries to assess','↗','Enquiries & Assessment'],[queue().filter(i=>i.title.startsWith('Send ')).length,'Documents ready to send','▤','My Tasks'],[queue().filter(i=>i.status==='Sent').length,'Awaiting client approval','◷','My Tasks'],[state.projects.filter(p=>ready(p)&&!p.mobilised).length,'Ready for mobilisation','✓','Projects']].map(([n,t,ic,d])=>`<button class="metric" data-page="${d}"><label>${t}<span>${ic}</span></label><strong>${String(n).padStart(2,'0')}</strong></button>`).join('')}</div><div class="grid"><div class="stack"><section class="card"><div class="cardhead"><div><h2>Action queue</h2><p class="muted">Assigned to ${esc(role)} · ${q.length} pending</p></div><button class="link" data-page="My Tasks">View all tasks →</button></div>${actionsTable(q)}</section><section class="card"><div class="cardhead"><h2>Projects in motion</h2><button class="link" data-page="Projects">Project library →</button></div>${projectTable(state.projects)}</section></div><aside class="stack"><section class="card pad"><div class="eyebrow">Team activity</div><h2>Latest handoffs</h2>${activityList()}</section><section class="card pad"><div class="eyebrow">Working together</div><h2>One project. Shared context.</h2><p class="muted">Client communications, approvals and delivery records stay connected through the Project ID.</p><button class="btn" data-action="guide">Test the workflow →</button></section></aside></div>`}
function activityList(p){let items=(p?p.events:state.projects.flatMap(p=>p.events.map(e=>({...e,project:p.name})))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,8);return items.length?items.map(e=>`<div class="activity"><strong><span class="dot"></span>${esc(e.text)}</strong><small>${esc(e.project||'')} ${esc(e.by)} · ${new Date(e.at).toLocaleDateString('en-GB')}</small></div>`).join(''):'<p class="muted">New activity will appear here.</p>'}
function stage(p){if(p.cancelled)return 'Cancelled';if(cancellationPending(p))return 'Cancellation review';if(p.mobilised)return 'Mobilised';if(ready(p))return 'Ready';if(acceptedQuote(p))return 'Pre-mobilisation';return 'Brief & quotation'}
function projectTable(ps){return ps.length?`<div class="tablewrap"><table><thead><tr><th>Project</th><th>Client</th><th>Stage</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${p.id} · ${esc(p.service)}</small></td><td>${esc(client(p).name)}</td><td>${badge(stage(p))}</td><td>${projectButton(p,'Open')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching projects.</div>'}
function enquiries(){let es=state.enquiries.filter(e=>[e.name,e.id,e.description].join(' ').toLowerCase().includes(search.toLowerCase()));return heading('Enquiries & assessment','Capture the conversation. Establish the next step.',btn('＋ New enquiry','newEnquiry','',true))+`<div class="toolbar"><input id="search" aria-label="Search enquiries" placeholder="Search name, enquiry ID or description…" value="${esc(search)}"></div><div class="card"><div class="tablewrap"><table><thead><tr><th>Prospective client</th><th>Service / route</th><th>Channel</th><th>Follow-up</th><th>Status</th><th></th></tr></thead><tbody>${es.map(e=>`<tr><td><strong>${esc(e.name)}</strong><small>${esc(e.id)}</small></td><td>${esc(e.service)}<small>${esc(e.route)}</small></td><td>${esc(e.channel)}</td><td>${esc(e.followup||'—')}</td><td>${badge(e.status)}</td><td><button class="btn small" data-enquiry="${e.id}">Review →</button></td></tr>`).join('')||'<tr><td colspan="6">No enquiries found.</td></tr>'}</tbody></table></div></div>`}
function team(){return heading('Team workspace','Coordinate client intake and project handoffs.')+`<div class="metrics">${[['Enquiries & Assessment','Capture and assess incoming work','↗'],['Clients','Client portfolios and contact records','♧'],['Projects','Shared project administration','▱'],['My Tasks','Actions across departments','✓']].map(([n,d,i])=>`<button class="metric" data-page="${n}"><label>${i}</label><h2>${n}</h2><p class="muted">${d}</p></button>`).join('')}</div>${projectTable(state.projects)}`}
function clientsPage(){return heading('Client portfolio','One client record, connected to every engagement.')+`<div class="card"><div class="tablewrap"><table><thead><tr><th>Client</th><th>Contact</th><th>Projects</th></tr></thead><tbody>${state.clients.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${c.id}</small></td><td>${esc(c.email||'—')}<small>${esc(c.phone)}</small></td><td>${state.projects.filter(p=>p.clientId===c.id).map(p=>projectButton(p,p.name)).join(' ')||'No projects'}</td></tr>`).join('')}</tbody></table></div></div>`}
function docsTable(p,ds){return ds.length?`<div class="tablewrap"><table><thead><tr><th>Document / version</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td><strong>${esc(d.type)} <span class="muted">v${d.version}</span></strong><small>${d.created}${d.sent?' · Sent '+esc(d.sent.date):''}</small></td><td>${d.total?money(d.total):'—'}</td><td>${badge(d.paid?'Confirmed':d.status)}</td><td><button class="btn small" data-doc="${d.id}" data-pid="${p.id}">Review →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No documents yet.</div>'}
function projectPage(){let p=currentProject();if(!p)return '';let c=client(p),q=acceptedQuote(p),s=sowOf(p);return heading(p.name,p.id+' · '+c.name+' · Job cycle '+cycleOf(p),`<button class="btn" data-page="Projects">← Projects</button>`)+`<div class="tabs">${['Overview','Brief & Quotation','Invoices & Payments','SOW & Mobilisation','Progress & Requests','Documents & Activity'].map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>`+({
'Overview':`<div class="grid"><div class="stack"><section class="card pad"><div class="row"><h2>Project snapshot</h2>${badge(stage(p))}</div><div class="formgrid" style="margin-top:24px">${[['Client ID',c.id],['Service',p.service],['Quotation route',p.route],['Contact',c.email||c.phone||'Not supplied']].map(([a,b])=>`<div><div class="muted">${a}</div><p>${esc(b)}</p></div>`).join('')}</div><div class="notice">${esc(p.brief||'Design can now record the client brief.')}</div></section><section class="card"><div class="cardhead"><h2>Project actions</h2></div>${actionsTable(queue().filter(i=>i.pid===p.id))}</section></div><aside class="card pad"><h2>Recent activity</h2>${activityList(p)}</aside></div>`+cancellationPanel(p),
'Brief & Quotation':briefPanel(p)+designRequestPanel(p)+`<div class="card"><div class="cardhead"><h2>Quotation versions · cycle ${cycleOf(p)}</h2>${!p.cancelled?btn('＋ Prepare quotation','quotation','',true):''}</div>${docsTable(p,p.docs.filter(d=>d.type.includes('quotation')))}</div>`,
'Invoices & Payments':`<div class="banner">Finance creates invoices from the accepted quotation. Confirming payment is a separate action from issuing or sending an invoice.</div><div class="card"><div class="cardhead"><h2>Invoices & payment confirmations</h2>${btn('＋ Create invoice','invoice','',true)}</div>${docsTable(p,p.docs.filter(d=>d.type==='Invoice'))}</div>`,
'SOW & Mobilisation':`<div class="grid"><section class="card"><div class="cardhead"><h2>Statement of work</h2>${btn('＋ Prepare SOW','sow','',true)}</div>${docsTable(p,p.docs.filter(d=>d.type==='SOW'))}</section><section class="card pad"><h2>Mobilisation readiness</h2>${[[!!q,'Quotation accepted','Exact version recorded'],[!!s?.headApproval,'Head of PM approval','Internal scope review'],[!!s?.mdApproval,'MD approval','Internal authorisation'],[s?.status==='Client approved','Client SOW approval','Recorded by Admin with evidence'],[p.docs.some(d=>d.type==='Invoice'&&d.initial&&d.paid&&d.quoteId===q?.id),'Deposit confirmed','Confirmed by Finance']].map(([ok,a,b])=>`<div class="gate"><span class="check ${ok?'done':''}">${ok?'✓':'·'}</span><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}<p class="muted">Both deposit confirmation and approval of the current SOW are required.</p>${p.cancelled?badge('Cancelled'):p.mobilised?badge('Mobilised'):role==='Head of PM'?btn('Authorise mobilisation','mobilise',ready(p)?'':'disabled',true):'<p class="notice">Head of PM authorises mobilisation once the deposit is confirmed and the client has approved the SOW.</p>'}</section></div>`,
'Progress & Requests':`<div class="banner">Milestones are defined against the SOW. Only Head of PM verification triggers linked actions. Procurement and expense approval screens are reserved for the next build.</div><div class="card"><div class="cardhead"><h2>SOW work milestones</h2>${btn('＋ Add milestone','milestone','',true)}</div><div class="tablewrap"><table><thead><tr><th>Work milestone</th><th>Linked actions</th><th>Status</th><th></th></tr></thead><tbody>${p.milestones.map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${m.evidence.length} evidence attachment(s)</small></td><td>${m.media?'Media visit':''}${m.media&&m.billing?' · ':''}${m.billing?m.billing+'% invoice':''}</td><td>${badge(m.status)}</td><td><button class="btn small" data-milestone="${m.id}">Open →</button></td></tr>`).join('')||'<tr><td colspan="4">No milestones defined.</td></tr>'}</tbody></table></div></div><section class="card" style="margin-top:20px"><div class="cardhead"><h2>Triggered departmental tasks</h2></div>${actionsTable(queue().filter(i=>i.pid===p.id&&i.source==='Verified work milestone'))}</section>`,
'Documents & Activity':`${historyButtons(p)}<div class="grid"><section class="card"><div class="cardhead"><h2>Project documents</h2></div>${docsTable(p,p.docs)}</section><section class="card pad"><h2>Activity history</h2>${activityList(p)}</section></div>`}[tab]||'')}
function documentPage(){let p=currentProject(),d=p.docs.find(d=>d.id===documentId),q=p.docs.find(x=>x.id===d.quoteId),current=(d.type==='SOW'?sowOf(p):d.type.includes('quotation')?quote(p):()=>d);let latest=typeof current==='function'?d:current;let buttons=[];if(d===latest&&!p.cancelled){if(['Draft','Changes requested','Price review requested'].includes(d.status)){if(d.type.includes('quotation')&&role==='PM')buttons.push(btn('Revise as new version','quotation','',true));if(d.type==='SOW'&&role==='PM')buttons.push(btn('Revise as new version','sow','',true))}if(d.status==='Revision requested')buttons.push(btn('Open design revision','designRevisionWorkspace'));if(d.status==='Submitted'&&role==='Admin')buttons.push(btn('Ready to send','reviewQuote','',true),btn('Return to PM','returnQuote'));if(d.status==='Awaiting Head of PM'&&role==='Head of PM')buttons.push(btn('Approve SOW','headSow','',true),btn('Request changes','returnSow'));if(d.status==='Awaiting MD'&&role==='MD')buttons.push(btn('Approve SOW','mdSow','',true),btn('Request changes','returnSow'));if(['Ready to send','Issued','Sent'].includes(d.status)&&role==='Admin')buttons.push(btn(d.sent?'Record resend':'Record as sent','send','',true));if(d.status==='Sent'&&d.type!=='Invoice'&&role==='Admin')buttons.push(btn('Record client approval','accept','',true),...(d.type.includes('quotation')?[btn('Request design/scope revision','requestDesign'),btn('Request price review','requestPrice')]:[btn('Record client changes','clientChanges')]));}if(!p.cancelled&&d.type==='Invoice'&&!d.paid&&['Finance','Head of Finance'].includes(role))buttons.push(btn('Confirm payment','paid','',true));return heading('Document review',p.name+' · '+p.id,btn('← Back to project','backProject'))+`<div class="grid"><div class="paper"><div class="row"><div class="paperlogo">OKIKE</div><span class="muted">PROTOTYPE DOCUMENT</span></div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><div class="eyebrow">${esc(d.type)} / version ${d.version}</div><h1>${esc(p.name)}</h1><p class="muted">Prepared for ${esc(client(p).name)} · ${d.created}</p>${d.designVersion?`<p class="muted">Design version ${d.designVersion} · Job cycle ${d.briefRevision||1}</p>`:''}${q?`<p class="muted">Based on ${esc(q.type)} v${q.version}</p>`:''}<p>${esc(d.body)}</p>${d.total?`<hr style="border:0;border-top:1px solid var(--line)"><div class="row"><h3>${d.type==='Invoice'?'Invoice amount':'Quotation total'}</h3><h2>${money(d.total)}</h2></div>`:''}<p class="muted" style="margin-top:40px">Demonstration record for workflow testing. This prototype does not calculate a construction BOQ or send documents to clients.</p></div><div class="stack"><section class="card pad"><div class="row"><h2>Document status</h2>${badge(d.paid?'Confirmed':d.status)}</div>${d!==latest?'<p class="notice">Historical version. Actions are available on the latest version.</p>':''}<p class="muted">${p.cancelled?'Cancelled job — records are read-only.':'Viewing as '+esc(role)+'. Approval actions follow the selected demo role.'}</p><div class="stack">${buttons.join('')||'<p class="muted">No action pending for this role.</p>'}</div><hr style="border:0;border-top:1px solid var(--line);margin:22px 0">${btn('↓ Download and send document','download')}${d.returnNote?`<p class="notice">${esc(d.returnNote)}</p>`:''}</section><section class="card pad"><h2>Dispatch & approval record</h2>${d.headApproval?'<p class="muted">✓ Head of PM approval recorded</p>':''}${d.mdApproval?'<p class="muted">✓ MD approval recorded</p>':''}${d.sent?`<p class="muted">Sent to ${esc(d.sent.recipient)} via ${esc(d.sent.channel)} on ${esc(d.sent.date)}.</p>`:'<p class="muted">No dispatch recorded.</p>'}${d.response?`<p class="notice">Client response: ${esc(d.response.note)}</p>${filesUI(d.response.files||[])}`:''}${d.payment?`<p class="notice">${money(d.payment.amount)} confirmed. Reference: ${esc(d.payment.reference)}</p>`:''}${filesUI(d.evidence||[])}</section></div></div>`}
function filesUI(fs){return fs.map(f=>`<div class="filelist"><a href="${esc(f.data)}" download="${esc(f.name)}">↓ ${esc(f.name)}</a></div>`).join('')}
function settings(){return heading('Settings','Appearance, feedback and prototype data.')+`<div class="card pad" style="max-width:750px">${[['theme','Dark mode'],['sound','Sound feedback'],['vibration','Vibration feedback'],['collapsed','Minimise sidebar']].map(([k,t])=>`<div class="gate row"><strong>${t}</strong><button class="btn small" data-pref="${k}">${(k==='theme'?prefs.theme==='dark':prefs[k])?'On':'Off'}</button></div>`).join('')}<p class="muted">Preferences and project records are saved in this browser. Demo roles are for testing and do not enforce secure account access.</p><div class="toolbar">${btn('Export test records','export')}${btn('Reset demo data','reset')}</div></div>`}
function render(){document.body.classList.toggle('dark',prefs.theme==='dark');document.body.classList.toggle('collapsed',prefs.collapsed);let navs=['My Workspace','My Tasks','Team Workspace','Messages','Company Documents','Policies & SOPs','Reporting Structure','Staff Directory'];let content=page==='Document'?documentPage():pid?projectPage():page==='My Workspace'?dashboard():page==='Enquiries & Assessment'?enquiries():page==='Team Workspace'?team():page==='Clients'?clientsPage():page==='Projects'?heading('Project library','Shared records across Administration, PM, Design and Finance.')+`<div class="toolbar"><input id="search" aria-label="Search projects" placeholder="Search projects or clients…" value="${esc(search)}"></div><div class="card">${projectTable(state.projects.filter(p=>(p.name+' '+p.id+' '+client(p).name).toLowerCase().includes(search.toLowerCase())))}</div>`:page==='My Tasks'?heading('Tasks & handoffs','Every action points back to its project and document.')+`<div class="toolbar"><select id="taskFilter" style="max-width:220px">${['All',...roles].map(r=>`<option ${taskFilter===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="card">${actionsTable(queue().filter(i=>taskFilter==='All'||i.dept===taskFilter))}</div>`:page==='Company Documents'?heading('Company documents','Project files grouped by originating department.')+state.projects.map(p=>`<section class="card" style="margin-bottom:20px"><div class="cardhead"><h2>${esc(p.name)} <span class="muted">${p.id}</span></h2>${projectButton(p)}</div><div class="pad"><h3>Finance folder</h3>${docsTable(p,p.docs.filter(d=>d.type==='Invoice'))}<h3>PM folder · Quotations & SOW</h3>${docsTable(p,p.docs.filter(d=>d.type!=='Invoice'))}</div></section>`).join(''):page==='Settings'?settings():heading(page,'Reserved in the shared Administration navigation.')+`<div class="card empty"><h2>${esc(page)}</h2><p>This area is outside the first workflow prototype.</p><button class="btn" data-page="My Workspace">Return to workspace</button></div>`;document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand">${prefs.collapsed?'O':'OKIKE'}<small>INTERNAL OPERATING SYSTEM</small></div><button class="nav" data-page="My Workspace"><span>⌂</span><span class="label">Home</span></button><button class="nav active" data-page="My Workspace"><span>▦</span><span class="label">Administration</span></button><div class="subnav">${navs.map(n=>`<button class="nav ${page===n?'active':''}" data-page="${n}">${n}</button>`).join('')}</div>${[['Finance','▤'],['Project Management','◇'],['Design','◩'],['Media','▧']].map(([n,i])=>`<button class="nav" data-module="${n}"><span>${i}</span><span class="label">${n}</span></button>`).join('')}<footer><button class="nav" data-page="Settings"><span>⚙</span><span class="label">Settings</span></button><button class="nav" data-pref="collapsed"><span>☰</span><span class="label">Minimise sidebar</span></button><small>OKIKE INTERNAL OS · v0.1</small></footer></aside><main class="main"><header class="topbar"><div class="crumb">OKIKE Internal OS <span style="margin:0 12px">/</span><b>Administration</b></div><div class="role"><span>DEMO ROLE</span><select id="role" aria-label="Demo role">${roles.map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select><button class="btn small" data-action="guide" aria-label="Testing guide">?</button><div class="avatar">${role.split(' ').map(x=>x[0]).slice(0,2).join('')}</div></div></header><div class="content"><div class="banner">WORKFLOW PROTOTYPE · Sample data · Changes save in this browser · No live messages or payments</div>${content}</div></main>`}
function go(p,id=null,t='Overview'){if(p==='My Tasks')taskFilter=role==='Head of Finance'?'Finance':role;page=p;pid=id;tab=t;search='';documentId=null;render();window.scrollTo(0,0)}
function dialog(title,body,form,submit='Save'){document.getElementById('modal').innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close">×</button></header>${form?`<form id="${form}">`:''}${body}${form?`<footer><button type="button" class="btn" data-close>Cancel</button><button class="btn primary" type="submit">${submit}</button></footer></form>`:''}</section></div>`;if(form&&pid){let f=document.getElementById(form);f.dataset.projectId=pid;f.dataset.cycle=String(cycleOf(currentProject()))}document.querySelector('.dialog input,.dialog textarea,.dialog select,.dialog button')?.focus()}
function close(){document.getElementById('modal').innerHTML=''}
const field=(label,name,value='',type='text',required=true)=>`<div><label class="fieldlabel" for="f-${name}">${label}${required?'':' (optional)'}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0.01" step="0.01"':''}></div>`;
const select=(label,name,opts,value)=>`<div><label class="fieldlabel" for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${opts.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
const area=(label,name,value='',required=true)=>`<div class="full"><label class="fieldlabel" for="f-${name}">${label}${required?'':' (optional)'}</label><textarea id="f-${name}" name="${name}" ${required?'required':''}>${esc(value)}</textarea></div>`;
const upload=(label='Attach evidence',required=false)=>`<div class="full"><label class="fieldlabel" for="f-files">${label}${required?'':' (optional)'}</label><input type="file" id="f-files" name="files" accept="image/*,application/pdf,text/plain" multiple ${required?'required':''}><p class="muted">Small images, PDFs or text files; combined maximum 1 MB per upload for this browser-only prototype.</p></div>`;
function newEnquiry(){if(role!=='Admin')return toast('Switch to Admin to capture an enquiry.',true);dialog('New client enquiry',`<div class="formgrid">${field('Contact name','name')}${field('Email','email','','email',false)}${field('Phone','phone','','tel',false)}${select('Channel','channel',['WhatsApp','Phone','Email','Instagram','Referral','Walk-in','Other'])}${select('Service','service',services)}${select('Preferred route','route',['Planning estimate','Design first'])}${field('Location','location','','text',false)}${field('Budget indication','budget','','text',false)}${field('Intended timeline','timeline','','text',false)}${field('Follow-up date','followup',today(),'date',false)}${area('Enquiry description','description')}</div>`,'enquiryForm','Save enquiry')}
let selectedEnquiry=null,selectedMilestone=null;
function assessment(id){selectedEnquiry=id;let e=state.enquiries.find(e=>e.id===id);dialog('Client assessment · '+e.id,`<p><strong>${esc(e.name)}</strong> · ${esc(e.channel)}</p><p class="muted">${esc(e.email)} ${esc(e.phone)} · ${esc(e.service)} · ${esc(e.route)}</p><p>${esc(e.description)}</p><p class="muted">Location: ${esc(e.location||'—')} · Budget: ${esc(e.budget||'—')} · Timeline: ${esc(e.timeline||'—')}</p>${e.status==='Accepted'?`<div class="notice">Accepted and linked to ${esc(e.projectId)}.</div><p><button class="btn" data-project="${e.projectId}" data-close>Open project</button></p>`:`<div class="formgrid">${select('Assessment outcome','status',['Follow-up needed','Accepted','Declined','Withdrawn'],e.status)}${field('Follow-up date','followup',e.followup,'date',false)}${area('Assessment notes','notes',e.notes)}<div class="full"><label class="fieldlabel">Link existing client, or create on acceptance</label><select name="clientId"><option value="">Create a new client</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)} · ${c.id}</option>`).join('')}</select></div>${field('Project name (required for acceptance)','projectName','','text',false)}</div>`}`,e.status==='Accepted'?null:'assessmentForm','Save assessment')}
async function readFiles(input){let fs=[...input.files];if(fs.reduce((n,f)=>n+f.size,0)>1000000)throw Error('Attachments exceed 1 MB. Please use smaller evidence files.');return Promise.all(fs.map(f=>new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res({name:f.name,data:r.result,type:f.type});r.onerror=()=>rej(Error('Could not read attachment.'));r.readAsDataURL(f)})))}
function documentAction(a){let p=currentProject(),d=p.docs.find(d=>d.id===documentId);if(['reviewQuote','headSow','mdSow'].includes(a)){if(mutate(()=>transition(p,d,a))){render();toast('Approval recorded. Next action is available.')}return}let body='';if(a==='send')body=`<div class="formgrid">${field('Recipient','recipient',client(p).email||client(p).phone)}${select('Channel','channel',['Email','WhatsApp','In person','Other'])}${field('Date sent','date',today(),'date')}${area('Dispatch note','note','',false)}</div><p class="notice">Send the downloaded document through your chosen channel, then record the actual dispatch here. This action does not send a message.</p>`;
else if(a==='paid')body=`<p class="notice">Confirm funds received for ${money(d.total)}. An issued invoice alone does not confirm payment.</p><div class="formgrid">${field('Amount received','amount',d.total,'number')}${field('Payment reference','reference')}${upload('Payment evidence')}</div>`;
else body=`<div class="formgrid">${area(a==='accept'?'Client approval evidence / reference':'Reason / client response','note')}${upload(a==='accept'?'Attach client approval':'Supporting evidence')}</div>`;
dialog(({send:'Record document dispatch',paid:'Confirm payment',accept:'Record client approval',clientChanges:'Record requested changes',returnQuote:'Return quotation to PM',returnSow:'Return SOW for changes'})[a],body,'docActionForm','Record');document.getElementById('docActionForm').dataset.action=a}
function prepare(kind){let p=currentProject(),q=acceptedQuote(p);assertActive(p);if(kind==='brief'){allow(['Design']);if(briefLocked(p))throw Error('The brief is locked. Start a new brief revision instead.');return dialog('Client brief · Design',area('Project requirements','body',p.brief),'briefForm')}
if(kind==='reviseBrief'){allow(['Design']);if(!canStartPostApprovalCycle(p))throw Error('Admin must route pre-approval design changes within this cycle.');if(!briefLocked(p))throw Error('Edit the current brief before quotation creation.');return dialog('Start new brief revision',`<p class="notice">Start cycle ${cycleOf(p)+1} under ${esc(p.id)}. Previous documents, approvals and payments stay in history. A new quotation and approval cycle is required; previous payments are not automatically credited.</p>${area('Revised client brief','body',p.brief)}${area('Reason for revision','reason')}`,'briefRevisionForm','Start new cycle')}

if(kind==='quotation'){if(role!=='PM')return toast('Switch to PM to prepare a quotation.',true);if(!p.brief)return toast('Record the client brief first.',true);if(quote(p)&&!['Draft','Changes requested','Price review requested'].includes(quote(p).status)&&!(quote(p).status==='Revision requested'&&latestDesignRequest(p)?.status==='Client confirmed'))return toast('The current quotation must be returned for changes before creating a revision.',true);return dialog('Prepare quotation',`<p class="notice">Enter a quotation summary and total to test the handoff. Integration with the existing quotation cost engine comes later.</p><div class="formgrid">${select('Quotation type','type',['Estimate quotation','Technical quotation'],p.route==='Planning estimate'?'Estimate quotation':'Technical quotation')}${field('Quotation total (₦)','total',quote(p)?.total||'','number')}${area('Scope and quotation summary','body',latestDesignRequest(p)?.status==='Client confirmed'?p.brief:(quote(p)?.body||p.brief))}${upload('Original quotation document')}</div>`,'quotationForm','Submit to Admin')}
if(!q)return toast('An accepted current quotation is required first.',true);
if(kind==='invoice'){if(!['Finance','Head of Finance'].includes(role))return toast('Switch to Finance to create an invoice.',true);let used=p.docs.filter(d=>d.type==='Invoice'&&d.quoteId===q.id).reduce((n,d)=>n+d.percent,0),ts=state.tasks.filter(t=>t.projectId===p.id&&t.dept==='Finance'&&t.status==='Open');if(used>=100)return toast('The approved quotation has already been fully invoiced.',true);if(used>0&&!ts.length)return toast('A verified work milestone with a billing condition is required for the next invoice.',true);return dialog('Create '+(used?'milestone':'deposit')+' invoice',`<p>Approved quotation: <strong>${money(q.total)}</strong></p><p class="muted">Already invoiced: ${used}%. Remaining: ${100-used}%.</p>${used?`<label class="fieldlabel">Verified billing milestone</label><select name="taskId">${ts.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select>`:''}<div class="formgrid" style="margin-top:16px">${field('Percentage of approved quotation','percent',used?p.milestones.find(m=>m.id===ts[0].milestoneId).billing:60,'number')}${field('Due date','due',today(),'date')}${area('Invoice note','body',used?'Milestone payment':'Initial deposit')}</div>`,'invoiceForm','Issue invoice')}
if(kind==='sow'){if(role!=='PM')return toast('Switch to PM to prepare the SOW.',true);if(sowOf(p)&&sowOf(p).status!=='Changes requested')return toast('The current SOW must be returned for changes before creating a revision.',true);return dialog('Prepare statement of work',`<p class="notice">Based on ${esc(q.type)} v${q.version}. Scope must match the accepted quotation.</p>${area('Scope, deliverables and work sequence','body',sowOf(p)?.body||q.body)}${upload('Supporting SOW document')}`,'sowForm','Submit to Head of PM')}
if(kind==='milestone'){if(role!=='PM')return toast('Switch to PM to define SOW work milestones.',true);if(!sowOf(p)||sowOf(p).status!=='Awaiting Head of PM')return toast('Add milestones while the SOW is awaiting Head of PM review. Request a revision if approval has already begun.',true);return dialog('Add SOW work milestone',`<div class="formgrid">${field('Work milestone','name')}${select('Trigger Media visit when verified','media',['No','Yes'])}<div><label class="fieldlabel">Linked invoice percentage (0 if none)</label><input name="billing" type="number" min="0" max="100" step="0.01" value="0" required></div></div><p class="muted">A billing percentage should reflect the agreed payment terms. Completion requires Head of PM verification.</p>`,'milestoneForm','Add milestone')}}
function milestoneDialog(id){selectedMilestone=id;let p=currentProject();assertActive(p);let m=p.milestones.find(m=>m.id===id);let content=`<p>${badge(m.status)}</p><p>${esc(m.note||'No completion report yet.')}</p>${filesUI(m.evidence)}`;if(['Planned','Changes requested'].includes(m.status)&&role==='PM')dialog(m.name,content+area('Completion report','note',m.note)+upload('Attach media evidence',true),'milestoneSubmitForm','Submit for verification');else if(m.status==='Submitted for Review'&&role==='Head of PM')dialog(m.name,content+`<footer>${btn('Return for changes','returnMilestone')}${btn('Verify & approve','verifyMilestone','',true)}</footer>`);else dialog(m.name,content+'<p class="muted">PM submits completion; Head of PM verifies and approves.</p>')}
function downloadFile(name,text,type='application/json'){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function guide(){dialog('Test a complete handoff',`<p>Use the <strong>Demo role</strong> selector to act as each department.</p><ol style="line-height:1.9;padding-left:20px"><li><strong>Admin:</strong> assess Tunde’s enquiry, accept it and name the project.</li><li><strong>Design:</strong> record the client brief in Brief & Quotation. PM accompanies for site familiarity.</li><li><strong>PM:</strong> submit the quotation, locking the brief.</li><li><strong>Admin:</strong> review it, record dispatch, then record client approval.</li><li><strong>Finance:</strong> issue the deposit invoice and confirm receipt when testing payment.</li><li><strong>PM:</strong> prepare the SOW. Add work milestones before submitting it for final approvals.</li><li><strong>Head of PM → MD:</strong> approve the SOW in sequence.</li><li><strong>Admin:</strong> record SOW dispatch and client approval.</li><li><strong>Head of PM:</strong> authorise mobilisation after Finance confirms the deposit and the client approves the SOW.</li><li><strong>PM:</strong> submit a milestone with a small media attachment.</li><li><strong>Head of PM:</strong> verify completion. Check the resulting departmental tasks.</li></ol><p class="notice">Before quotation acceptance, Admin chooses Request design/scope revision or Request price review. Design revisions require client scope confirmation before PM reprices. After acceptance and invoicing or payment, changes start a new job cycle under the same IDs. For a below-threshold client offer after baseline revision, Head of PM requests cancellation from the project Overview; MD decides.</p><p class="notice">Cedar House starts at quotation review. Palmcrest starts at invoicing and SOW approval. Use Settings to export test records or reset the samples.</p><p class="muted">Browser-local prototype: no real authentication, shared database, live delivery or payments.</p>`)}
document.addEventListener('click',e=>{let b=e.target.closest('button,a');if(!b)return;try{if(b.hasAttribute('data-close'))close();if(b.dataset.cycle){showCycle(b.dataset.cycle);return}if(b.dataset.cancelDecision){cancellationDecisionForm(b.dataset.cancelDecision);return}if(b.dataset.historyDownload){let p=currentProject(),c=p.previousCycles.find(c=>c.revision===Number(b.dataset.cycleId)),d=c.docs.find(d=>d.id===b.dataset.historyDownload);downloadFile(p.id+'-cycle-'+c.revision+'-'+d.type.replaceAll(' ','-')+'-v'+d.version+'.txt',`OKIKE — ARCHIVED DOCUMENT\n${p.id} · Cycle ${c.revision}\n${d.type} v${d.version}\n\n${d.body}\n${d.total?money(d.total):''}`, 'text/plain');return}if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.project){go('Project',b.dataset.project,b.dataset.tab||'Overview');return}if(b.dataset.tab){tab=b.dataset.tab;page='Project';render();return}if(b.dataset.doc){pid=b.dataset.pid;documentId=b.dataset.doc;page='Document';render();window.scrollTo(0,0);return}if(b.dataset.enquiry){assessment(b.dataset.enquiry);return}if(b.dataset.milestone){milestoneDialog(b.dataset.milestone);return}if(b.dataset.pref){let k=b.dataset.pref;let prev={...prefs};prefs[k]=k==='theme'?(prefs.theme==='dark'?'light':'dark'):!prefs[k];try{localStorage.setItem(PREF,JSON.stringify(prefs))}catch{prefs=prev;toast('Could not save preferences.',true)}render();return}if(b.dataset.module){dialog(b.dataset.module,`<p>This prototype focuses on Administration. Use the demo role selector to test ${esc(b.dataset.module)} handoffs within the shared project workspace.</p><button class="btn" data-page="My Tasks" data-close>Open cross-department tasks</button>`);return}let a=b.dataset.action;if(!a)return;if(['requestDesign','requestPrice','prepareDesign','sendDesign','confirmDesign','changesDesign'].includes(a))return openRevisionAction(a);if(a==='designRevisionWorkspace')return go('Project',pid,'Brief & Quotation');if(a==='requestCancellation')return cancellationForm();if(a==='newEnquiry')return newEnquiry();if(a==='guide')return guide();if(a==='backProject')return go('Project',pid,'Documents & Activity');if(['brief','reviseBrief','quotation','invoice','sow','milestone'].includes(a))return prepare(a);if(['reviewQuote','returnQuote','headSow','mdSow','returnSow','send','accept','clientChanges','paid'].includes(a))return documentAction(a);if(a==='mobilise'){if(mutate(()=>{authoriseMobilisation(currentProject())})){render();toast('Mobilisation authorised.')}return}if(a==='verifyMilestone'){if(mutate(()=>approveMilestone(currentProject(),currentProject().milestones.find(m=>m.id===selectedMilestone)))){close();render();toast('Milestone verified. Linked tasks created.')}return}if(a==='returnMilestone'){dialog('Return milestone for changes',area('Reason','note'),'returnMilestoneForm','Return to PM');return}if(a==='download'){let p=currentProject(),d=p.docs.find(d=>d.id===documentId);downloadFile(p.id+'-cycle-'+cycleOf(p)+'-'+d.type.replaceAll(' ','-')+'-v'+d.version+'.txt',`OKIKE — WORKFLOW PROTOTYPE\n${d.type} v${d.version}\nProject: ${p.name} / ${p.id}\nClient: ${client(p).name}\n\n${d.body}\n\n${d.total?'Total: '+money(d.total):''}\n\nDemonstration document.`, 'text/plain');toast('Downloaded. Dispatch status is unchanged.');return}if(a==='export')return downloadFile('OKIKE-Administration-test-records.json',JSON.stringify(state,null,2));if(a==='reset')return dialog('Reset prototype data?',`<p>This replaces your locally saved test records and attachments with the original sample projects. Export records first if you need to keep them.</p>`,'resetForm','Reset demo data')}catch(err){toast(err.message,true)}});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;taskFilter=role==='Head of Finance'?'Finance':role;render()}if(e.target.id==='taskFilter'){taskFilter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;search=e.target.value;render();let x=document.getElementById('search');x.focus();x.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&document.querySelector('.dialog')){let els=[...document.querySelectorAll('.dialog button,.dialog input,.dialog select,.dialog textarea,.dialog a')].filter(x=>!x.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target;if(!f.checkValidity()){f.reportValidity();return}let submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{let data=Object.fromEntries(new FormData(f));for(let k in data)if(typeof data[k]==='string')data[k]=data[k].trim();if(f.querySelector('[name=files]'))data.files=await readFiles(f.querySelector('[name=files]'));let target=null;let ok=mutate(()=>{let p=currentProject();if(f.dataset.projectId){assertCycle(p,f.dataset.projectId,f.dataset.cycle);assertActive(p)}switch(f.id){case 'enquiryForm':allow(['Admin']);if(!data.name||!data.description||(!data.email&&!data.phone))throw Error('Add a name, description and at least one contact method.');state.enquiries.unshift({...data,id:uid('ENQ'),status:'New',notes:'',owner:'Admin',created:today()});break;
case 'assessmentForm':{allow(['Admin']);let en=state.enquiries.find(x=>x.id===selectedEnquiry);if(!data.notes)throw Error('Record assessment notes.');if(data.status==='Accepted'){if(!data.projectName)throw Error('Enter the project name before accepting.');let c=state.clients.find(x=>x.id===data.clientId);if(!c){let duplicate=state.clients.find(x=>(en.email&&x.email.toLowerCase()===en.email.toLowerCase())||(en.phone&&x.phone===en.phone));if(duplicate)throw Error('An existing client matches this contact. Select '+duplicate.name+' to reuse their Client ID.');c={id:uid('CL'),name:en.name,email:en.email,phone:en.phone};state.clients.push(c)}let pr=project(uid('OK'),data.projectName,c.id);pr.service=en.service;pr.route=en.route;pr.enquiryId=en.id;state.projects.push(pr);log(pr,'Enquiry accepted. Design owns brief collection; PM accompanies for site familiarity and the client relationship.');en.projectId=pr.id;target=pr.id}en.status=data.status;en.notes=data.notes;en.followup=data.followup;break}
case 'briefForm':saveBrief(p,data.body);break;
case 'briefRevisionForm':startBriefRevision(p,data.body,data.reason);tab='Brief & Quotation';break;
case 'cancellationForm':requestCancellation(p,data);break;
case 'cancellationDecisionForm':decideCancellation(p,f.dataset.requestId,data.decision,data.note);break;
case 'quotationForm':submitQuotation(p,data);break;
case 'invoiceForm':{allow(['Finance','Head of Finance']);let q=acceptedQuote(p);if(!q)throw Error('Accepted quotation required.');let used=p.docs.filter(d=>d.type==='Invoice'&&d.quoteId===q.id).reduce((n,d)=>n+d.percent,0),pct=Number(data.percent);if(pct<=0||pct>100-used)throw Error('Invoice percentage exceeds the remaining quotation balance.');let task;if(used>0){task=state.tasks.find(t=>t.id===data.taskId&&t.projectId===p.id&&t.status==='Open'&&t.dept==='Finance');if(!task)throw Error('Select an open verified milestone billing task.');if(pct!==p.milestones.find(m=>m.id===task.milestoneId).billing)throw Error('Percentage must match the agreed milestone billing condition.')}let d=doc('Invoice',p.docs.filter(d=>d.type==='Invoice').length+1,data.body,Math.round(q.total*pct)/100);Object.assign(d,{status:'Issued',quoteId:q.id,percent:pct,initial:used===0,due:data.due,paid:false});p.docs.push(d);if(task)task.status='Completed';log(p,'Finance issued '+pct+'% invoice. Admin and PM notified.');break}
case 'sowForm':{allow(['PM']);let q=acceptedQuote(p),prev=sowOf(p);if(!q)throw Error('Accepted quotation required.');if(prev&&prev.status!=='Changes requested')throw Error('Current SOW is not open for revision.');if(!data.body)throw Error('Enter the statement of work.');let d=doc('SOW',(prev?.version||0)+1,data.body);Object.assign(d,{quoteId:q.id,status:'Awaiting Head of PM',evidence:data.files});p.docs.push(d);log(p,'SOW v'+d.version+' submitted to Head of PM.');break}
case 'requestDesignForm':requestQuoteChange(p,p.docs.find(d=>d.id===documentId),'design',data);break;
case 'requestPriceForm':requestQuoteChange(p,p.docs.find(d=>d.id===documentId),'price',data);break;
case 'prepareDesignForm':saveDesignRevision(p,data);break;
case 'sendDesignForm':recordDesignResponse(p,'send',data);break;
case 'confirmDesignForm':recordDesignResponse(p,'confirm',data);break;
case 'changesDesignForm':recordDesignResponse(p,'changes',data);break;
case 'docActionForm':{let d=p.docs.find(d=>d.id===documentId);if(['accept','clientChanges','returnQuote','returnSow'].includes(f.dataset.action)&&!data.note)throw Error('Record the response or supporting reference.');transition(p,d,f.dataset.action,data);break}
case 'milestoneForm':{allow(['PM']);if(!sowOf(p)||sowOf(p).status!=='Awaiting Head of PM')throw Error('Milestones can only be added before Head of PM approval.');if(!data.name)throw Error('Name the milestone.');let s=sowOf(p);if(s.status!=='Awaiting Head of PM'){s.status='Awaiting Head of PM';delete s.headApproval;delete s.mdApproval;s.sent=null;log(p,'SOW milestone change requires renewed internal approval.')}p.milestones.push({id:uid('MS'),name:data.name,media:data.media==='Yes',billing:Number(data.billing),status:'Planned',note:'',evidence:[]});s.body+='\n\nWork milestone: '+data.name+(data.media==='Yes'?' · Media visit on verified completion':'')+(Number(data.billing)?' · Billing condition: '+data.billing+'%':'');log(p,'SOW work milestone defined: '+data.name);break}
case 'milestoneSubmitForm':{allow(['PM']);if(!p.mobilised)throw Error('Mobilisation must be authorised before reporting completion.');let m=p.milestones.find(m=>m.id===selectedMilestone);if(!['Planned','Changes requested'].includes(m.status))throw Error('Milestone is not open for submission.');if(!data.files.length||!data.note)throw Error('Add a completion report and media evidence.');m.note=data.note;m.evidence=data.files;m.status='Submitted for Review';log(p,'Milestone submitted for Head of PM verification: '+m.name);break}
case 'returnMilestoneForm':{allow(['Head of PM']);let m=p.milestones.find(m=>m.id===selectedMilestone);if(m.status!=='Submitted for Review')throw Error('Milestone is not awaiting verification.');m.status='Changes requested';m.note+='\nHead of PM review: '+data.note;log(p,'Milestone returned for changes: '+m.name);break}
case 'resetForm':state=seed();page='My Workspace';pid=null;documentId=null;break;
default:throw Error('Unknown form.')}});if(ok){close();if(target)go('Project',target);else if(page==='Document'&&['quotationForm','sowForm'].includes(f.id))go('Project',pid,f.id==='quotationForm'?'Brief & Quotation':'SOW & Mobilisation');else render();toast('Saved. Workspace updated.')}}catch(err){toast(err.message,true)}finally{if(submit)submit.disabled=false}});
// Project-cycle rules. Existing browser records default to cycle 1.
function cycleOf(p){return p.briefRevision||1}
function briefLocked(p){return p.docs.some(d=>d.type.includes('quotation'))}
function cancellationPending(p){return (p.cancellationRequests||[]).some(r=>r.status==='Awaiting MD')}
function assertActive(p){if(p?.cancelled)throw Error('This job has been cancelled by MD. Its records are read-only.');}
function assertCycle(p,id,cycle){if(!p||p.id!==id||cycleOf(p)!==Number(cycle))throw Error('This form belongs to an earlier job cycle. Reopen the current action.');}
function saveBrief(p,body){
 allow(['Design']);assertActive(p);body=String(body||'').trim();
 if(briefLocked(p))throw Error('The brief is locked because a quotation exists. Start a new brief revision instead.');
 if(!body)throw Error('Enter the client brief.');
 p.brief=body;p.briefEditedBy='Design';p.briefEditedAt=new Date().toISOString();
 state.tasks.filter(t=>t.projectId===p.id&&t.key===p.id+'brief').forEach(t=>t.status='Completed');
 log(p,'Design saved client brief · cycle '+cycleOf(p)+'. PM can prepare a quotation.');
}
function startBriefRevision(p,body,reason){
 allow(['Design']);assertActive(p);body=String(body||'').trim();reason=String(reason||'').trim();
 if(cancellationPending(p))throw Error('MD must resolve the pending cancellation request before a new cycle starts.');
 if(!briefLocked(p))throw Error('No quotation exists yet. Edit the current brief instead.');
 if(!body||body===p.brief.trim())throw Error('Enter a changed brief to start a new cycle.');
 if(!reason)throw Error('Record why the brief is changing.');if(!canStartPostApprovalCycle(p))throw Error('Before quotation acceptance, Admin must request design/scope revision within the current cycle.');
 const revision=cycleOf(p), snapshot=JSON.parse(JSON.stringify({revision,brief:p.brief,designVersion:p.designVersion||1,designRequests:p.designRequests||[],docs:p.docs,milestones:p.milestones,mobilised:p.mobilised,mobilisationApproval:p.mobilisationApproval||null,events:p.events,cancellationRequests:p.cancellationRequests||[],tasks:state.tasks.filter(t=>t.projectId===p.id),closedAt:new Date().toISOString(),reason}));
 p.previousCycles=[...(p.previousCycles||[]),snapshot];
 state.tasks.filter(t=>t.projectId===p.id&&t.status==='Open').forEach(t=>t.status='Superseded');
 p.briefRevision=revision+1;p.brief=body;p.briefEditedBy='Design';p.briefEditedAt=new Date().toISOString();
 p.docs=[];p.designRequests=[];p.designVersion=1;p.milestones=[];p.mobilised=false;p.mobilisationApproval=null;p.cancellationRequests=[];
 log(p,'Design started cycle '+cycleOf(p)+': '+reason+'. New quotation and approvals required.');
}
function submitQuotation(p,data){
 allow(['PM']);assertActive(p);if(cancellationPending(p))throw Error('MD must resolve the pending cancellation request before another quotation is created.');if(!p.brief.trim())throw Error('Design must record the client brief first.');
 if(!String(data.body||'').trim()||!Number.isFinite(Number(data.total))||Number(data.total)<=0)throw Error('Enter a scope and positive quotation amount.');
 if(!['Estimate quotation','Technical quotation'].includes(data.type))throw Error('Select a quotation type.');
 let previous=quote(p);if(previous&&!['Changes requested','Draft','Price review requested'].includes(previous.status)&&!(previous.status==='Revision requested'&&latestDesignRequest(p)?.status==='Client confirmed'))throw Error('Current quotation is not open for revision.');
 if(previous?.status==='Price review requested'&&data.body.trim()!==previous.body.trim())throw Error('Price review must keep the scope unchanged. Ask Admin to request a design/scope revision for scope changes.');
 let d=doc(data.type,(previous?.version||0)+1,data.body,Number(data.total));
 Object.assign(d,{evidence:data.files||[],status:'Submitted',briefSnapshot:p.brief,briefRevision:cycleOf(p),designVersion:p.designVersion||1,replacesQuoteId:previous?.id||null});
 p.docs.push(d);let dr=latestDesignRequest(p);if(dr?.status==='Client confirmed'){dr.status='Quoted';dr.replacementQuoteId=d.id}log(p,d.type+' v'+d.version+' submitted for Admin review. Client brief is locked.');return d;
}
function authoriseMobilisation(p){
 allow(['Head of PM']);assertActive(p);if(!ready(p))throw Error('Finance-confirmed deposit and client-approved SOW are required; pending cancellation must be resolved.');
 if(p.mobilised)throw Error('Mobilisation is already authorised.');
 p.mobilised=true;p.mobilisationApproval={by:role,at:new Date().toISOString(),cycle:cycleOf(p)};
 log(p,'Head of PM authorised mobilisation.');
}
function revisedBaseline(p){return !!quote(p)&&(quote(p).version>1||cycleOf(p)>1)}
function requestCancellation(p,data){
 allow(['Head of PM']);assertActive(p);
 if(!revisedBaseline(p))throw Error('Create a revised quotation baseline before requesting cancellation.');
 if(cancellationPending(p))throw Error('A cancellation request is already awaiting MD.');
 const threshold=Number(data.threshold),offerMargin=Number(data.offerMargin),offer=Number(data.offer);
 if(!Number.isFinite(threshold)||threshold<0||threshold>=100||!Number.isFinite(offerMargin)||offerMargin>=threshold||offerMargin < -1000)throw Error('Enter a valid margin threshold and a client-offer margin below that threshold.');
 if(!Number.isFinite(offer)||offer<=0||!String(data.reason||'').trim())throw Error('Record the client offer and reason, including evidence that the client insists on it.');
 const r={id:uid('CANCEL'),cycle:cycleOf(p),quoteId:quote(p).id,quoteVersion:quote(p).version,baselineTotal:quote(p).total,threshold,offerMargin,offer,reason:data.reason,files:data.files||[],status:'Awaiting MD',requestedBy:role,requestedAt:new Date().toISOString()};
 p.cancellationRequests=[...(p.cancellationRequests||[]),r];log(p,'Head of PM requested job cancellation after baseline revision. MD approval required.');return r;
}
function decideCancellation(p,id,decision,note){
 allow(['MD']);assertActive(p);const r=(p.cancellationRequests||[]).find(r=>r.id===id);
 if(!r||r.status!=='Awaiting MD'||r.cycle!==cycleOf(p)||r.quoteId!==quote(p)?.id)throw Error('This cancellation request is no longer pending.');
 if(!['Approved','Rejected'].includes(decision)||!String(note||'').trim())throw Error('Record the MD decision and reason.');
 Object.assign(r,{status:decision,decisionNote:note,decidedBy:role,decidedAt:new Date().toISOString()});
 if(decision==='Approved'){p.cancelled=true;p.cancelledAt=r.decidedAt;state.tasks.filter(t=>t.projectId===p.id&&t.status==='Open').forEach(t=>t.status='Cancelled');}
 log(p,decision==='Approved'?'MD approved job cancellation. Job closed; records retained.':'MD rejected job cancellation. Workflow can continue.');
}
function briefPanel(p){let locked=briefLocked(p);return `<div class="card pad" style="margin-bottom:20px"><div class="row"><div><h2>Client brief</h2><p class="muted">Job cycle ${cycleOf(p)} · ${locked?'Locked after quotation creation':'Editable by Design before quotation creation'}</p></div>${role==='Design'&&!p.cancelled&&(!locked||canStartPostApprovalCycle(p))?btn(locked?'Start new job cycle':'Edit brief',locked?'reviseBrief':'brief','',true):badge('Design only')}</div><p style="white-space:pre-wrap">${esc(p.brief||'Design has not recorded the client brief yet.')}</p><p class="muted">Design collects and edits the brief. PM accompanies Design for site familiarity and the client relationship.</p>${locked?'<div class="notice">Before acceptance, Admin routes design/scope changes to Design or price review to PM. After acceptance, Design starts a new job cycle; existing approvals and payments stay in history.</div>':''}${historyButtons(p)}</div>`}
function historyButtons(p){return (p.previousCycles||[]).length?`<h3>Previous job cycles</h3>${p.previousCycles.map(c=>`<div class="row activity"><div><strong>Cycle ${c.revision} · ${c.docs.length} document(s)</strong><small>${esc(c.reason)}</small></div><button class="btn small" data-cycle="${c.revision}">View history</button></div>`).join('')}`:''}
function showCycle(revision){let p=currentProject(),c=(p.previousCycles||[]).find(c=>c.revision===Number(revision));if(!c)return;dialog('Job cycle '+c.revision+' · History',`<p class="notice">Read-only history. Previous approvals and payment records do not authorise the current cycle.</p><h3>Client brief</h3><p style="white-space:pre-wrap">${esc(c.brief)}</p><p class="muted">Revision reason: ${esc(c.reason)}</p><h3>Documents and decisions</h3>${c.docs.map(d=>`<div class="card pad" style="margin-bottom:12px"><div class="row"><strong>${esc(d.type)} v${d.version}</strong>${badge(d.paid?'Confirmed':d.status)}</div><p style="white-space:pre-wrap">${esc(d.body)}</p>${d.total?`<p>${money(d.total)}</p>`:''}${d.sent?`<p class="muted">Sent ${esc(d.sent.date)} to ${esc(d.sent.recipient)}</p>`:''}${d.response?`<p class="muted">Client response: ${esc(d.response.note)}</p>${filesUI(d.response.files||[])}`:''}${d.headApproval?'<p class="muted">Head of PM approved</p>':''}${d.mdApproval?'<p class="muted">MD approved</p>':''}${d.payment?`<p class="muted">Payment confirmed: ${money(d.payment.amount)} · ${esc(d.payment.reference)}</p>`:''}${filesUI(d.evidence||[])}<button class="btn small" data-history-download="${d.id}" data-cycle-id="${c.revision}">Download archived document</button></div>`).join('')}<h3>Milestones</h3>${c.milestones.map(m=>`<p>${esc(m.name)} · ${esc(m.status)}</p>${filesUI(m.evidence||[])}`).join('')||'<p class="muted">No milestones.</p>'}<p class="muted">Mobilisation in that cycle: ${c.mobilised?'authorised':'not authorised'}.</p>`)}
function cancellationPanel(p){let requests=p.cancellationRequests||[];return `<section class="card pad" style="margin-top:20px"><div class="row"><div><h2>Job cancellation</h2><p class="muted">Head of PM requests · MD decides</p></div>${role==='Head of PM'&&!p.cancelled?btn('Request job cancellation','requestCancellation',revisedBaseline(p)&&!cancellationPending(p)?'':'disabled'):''}</div>${!revisedBaseline(p)?'<p class="muted">Available after a revised quotation baseline has been created.</p>':''}${requests.map(r=>`<div class="activity"><div class="row"><strong>Cycle ${r.cycle} · Quotation v${r.quoteVersion}</strong>${badge(r.status)}</div><p class="muted">Revised baseline: ${money(r.baselineTotal)} · Client offer: ${money(r.offer)}<br>Minimum margin: ${r.threshold}% · Offered margin: ${r.offerMargin}%</p><p>${esc(r.reason)}</p>${filesUI(r.files)}${r.decisionNote?`<p class="notice">MD ${esc(r.status.toLowerCase())}: ${esc(r.decisionNote)}</p>`:''}${r.status==='Awaiting MD'&&role==='MD'?`<button class="btn primary" data-cancel-decision="${r.id}">Review cancellation request</button>`:''}</div>`).join('')||'<p class="muted">No cancellation request submitted.</p>'}</section>`}
function cancellationForm(){let p=currentProject();allow(['Head of PM']);assertActive(p);if(!revisedBaseline(p))throw Error('A revised quotation baseline is required.');dialog('Request job cancellation',`<p class="notice">For a client insisting on an offer below the margin threshold after baseline revision. This submits a request to MD; it does not cancel the job. Margins are entered for review, not calculated by the quotation engine in this prototype.</p><div class="formgrid">${field('Client offer (₦)','offer','','number')}${field('Minimum permitted margin (%)','threshold','','number')}<div><label class="fieldlabel" for="f-offerMargin">Margin at client offer (%)</label><input id="f-offerMargin" name="offerMargin" type="number" min="-1000" max="99.99" step="0.01" required></div>${area('Reason and client insistence evidence / reference','reason')}${upload('Supporting evidence')}</div>`,'cancellationForm','Notify MD')}
function cancellationDecisionForm(id){allow(['MD']);let p=currentProject(),r=p.cancellationRequests.find(r=>r.id===id);if(!r||r.status!=='Awaiting MD')throw Error('Request is no longer pending.');dialog('MD cancellation decision',`<p>${esc(r.reason)}</p><p class="muted">Client offer margin ${r.offerMargin}% · Threshold ${r.threshold}%</p>${select('Decision','decision',['Rejected','Approved'])}${area('Decision reason','note')}<p class="notice">Approval cancels this job and closes its pending tasks. Previous documents and payment records remain available.</p>`,'cancellationDecisionForm','Record decision');document.getElementById('cancellationDecisionForm').dataset.requestId=id;}

function latestDesignRequest(p){return (p.designRequests||[]).at(-1)}
function canStartPostApprovalCycle(p){return quote(p)?.status==='Accepted'}
function requestQuoteChange(p,d,kind,data){
 allow(['Admin']);assertActive(p);
 if(d!==quote(p)||d.status!=='Sent'||!d.type.includes('quotation'))throw Error('Changes can only be requested against the current sent, unaccepted quotation.');
 if(!['design','price'].includes(kind)||!String(data.note||'').trim())throw Error('Record the client request and choose a revision route.');
 const request={id:uid('REV'),quoteId:d.id,quoteVersion:d.version,kind,note:data.note,files:data.files||[],requestedAt:new Date().toISOString(),cycle:cycleOf(p)};
 d.response={note:data.note,files:data.files||[],date:today()};d.changeRequest=request;
 if(kind==='design'){
  d.status='Revision requested';
  p.designRequests=[...(p.designRequests||[]),{...request,status:'Awaiting Design',originalBrief:p.brief,designVersion:(p.designVersion||1)+1,proposedBrief:'',designNotes:'',designFiles:[]}];
  log(p,'Admin requested design/scope revision on quotation v'+d.version+'. Design notified; quotation acceptance and invoicing blocked.');
 }else{d.status='Price review requested';log(p,'Admin requested price review of quotation v'+d.version+'. PM notified; design and brief remain unchanged.');}
}
function saveDesignRevision(p,data){
 allow(['Design']);assertActive(p);const r=latestDesignRequest(p);
 if(!r||!['Awaiting Design','Client requested design changes'].includes(r.status))throw Error('No design revision is awaiting Design.');
 if(!String(data.body||'').trim()||!String(data.designNotes||'').trim())throw Error('Record the revised brief and design/specification changes.');
 r.proposedBrief=data.body.trim();r.designNotes=data.designNotes.trim();r.designFiles=data.files||[];r.status='Ready for client review';r.preparedBy=role;r.preparedAt=new Date().toISOString();
 log(p,'Design revision '+r.designVersion+' ready. Admin must send it for client scope confirmation before PM reprices.');
}
function recordDesignResponse(p,action,data){
 allow(['Admin']);assertActive(p);const r=latestDesignRequest(p);
 if(!r)throw Error('No design revision found.');
 if(action==='send'){
  if(r.status!=='Ready for client review')throw Error('Design must prepare the revision first.');
  if(!data.recipient||!data.channel||!data.date)throw Error('Record recipient, channel and date sent.');
  r.sent={recipient:data.recipient,channel:data.channel,date:data.date};r.status='Sent for client confirmation';
  log(p,'Admin sent design revision '+r.designVersion+' for client confirmation.');
 }else{
  if(r.status!=='Sent for client confirmation')throw Error('Send the design revision before recording the response.');
  if(!String(data.note||'').trim())throw Error('Record the client response evidence or reference.');
  const response={note:data.note,files:data.files||[],date:today()};r.responses=[...(r.responses||[]),response];r.clientResponse=response;
  if(action==='confirm'){
   r.status='Client confirmed';p.brief=r.proposedBrief;p.designVersion=r.designVersion;p.briefEditedBy='Design';p.briefEditedAt=r.preparedAt;
   log(p,'Client confirmed design revision '+r.designVersion+'. PM notified to prepare replacement quotation; price acceptance is still required.');
  }else if(action==='changes'){r.attempts=[...(r.attempts||[]),{brief:r.proposedBrief,notes:r.designNotes,files:r.designFiles,sent:r.sent,response}];r.status='Client requested design changes';r.sent=null;log(p,'Client requested further design changes. Returned to Design.');}
  else throw Error('Unknown design response.');
 }
}
function designRequestPanel(p){const r=latestDesignRequest(p);if(!r)return '';let actions='';
 if(!p.cancelled&&role==='Design'&&['Awaiting Design','Client requested design changes'].includes(r.status))actions=btn('Prepare design revision','prepareDesign','',true);
 if(!p.cancelled&&role==='Admin'&&r.status==='Ready for client review')actions=btn('Record revised design as sent','sendDesign','',true);
 if(!p.cancelled&&role==='Admin'&&r.status==='Sent for client confirmation')actions=btn('Confirm revised scope','confirmDesign','',true)+' '+btn('Request further design changes','changesDesign');
 if(!p.cancelled&&role==='PM'&&r.status==='Client confirmed')actions=btn('Prepare replacement quotation','quotation','',true);
 return `<section class="card pad" style="margin-bottom:20px"><div class="row"><div><h2>Design / scope revision ${r.designVersion}</h2><p class="muted">Quotation v${r.quoteVersion} · Current job cycle ${cycleOf(p)}</p></div>${badge(r.status)}</div><p>${esc(r.note)}</p>${filesUI(r.files)}${r.proposedBrief?`<h3>Revised brief</h3><p style="white-space:pre-wrap">${esc(r.proposedBrief)}</p><h3>Design / specification changes</h3><p style="white-space:pre-wrap">${esc(r.designNotes)}</p>${filesUI(r.designFiles)}`:''}${r.sent?`<p class="muted">Sent to ${esc(r.sent.recipient)} via ${esc(r.sent.channel)} on ${esc(r.sent.date)}</p>`:''}${r.clientResponse?`<p class="notice">Client response: ${esc(r.clientResponse.note)}</p>${filesUI(r.clientResponse.files)}`:''}<p class="muted">Scope confirmation authorises repricing; it does not approve the quotation amount.</p><div class="toolbar">${actions}</div></section>`;
}
function openRevisionAction(action){const p=currentProject();assertActive(p);
 if(['requestDesign','requestPrice'].includes(action)){allow(['Admin']);return dialog(action==='requestDesign'?'Request design / scope revision':'Request price review',`<p class="notice">${action==='requestDesign'?'Design will revise the scope. The client must confirm the revised design before PM prepares a replacement quotation.':'PM will review pricing for the same brief and scope. Design will not receive this task.'}</p>${area('Client request / evidence reference','note')}${upload('Client message or supporting files')}` ,action==='requestDesign'?'requestDesignForm':'requestPriceForm','Submit request');}
 const r=latestDesignRequest(p);if(!r)throw Error('No design revision found.');
 if(action==='prepareDesign'){allow(['Design']);return dialog('Prepare design revision',`<p class="notice">Client request: ${esc(r.note)}. Record design-fee or timing implications in the notes for Admin to communicate.</p>${area('Revised client brief','body',r.proposedBrief||r.originalBrief)}${area('Design / specification changes and implications','designNotes',r.designNotes)}${upload('Revised design files')}`,'prepareDesignForm','Send to Admin');}
 if(action==='sendDesign'){allow(['Admin']);return dialog('Record revised design dispatch',`<p class="notice">Send the revised design and brief through your chosen channel, then record the actual dispatch here.</p><div class="formgrid">${field('Recipient','recipient',client(p).email||client(p).phone)}${select('Channel','channel',['Email','WhatsApp','In person','Other'])}${field('Date sent','date',today(),'date')}</div>`,'sendDesignForm','Record dispatch');}
 allow(['Admin']);dialog(action==='confirmDesign'?'Confirm revised scope':'Further design changes',`${area('Client response evidence / reference','note')}${upload('Client confirmation or feedback')}`,action==='confirmDesign'?'confirmDesignForm':'changesDesignForm','Record response');
}

